def parse():
    """Yield (brand, caliber_name, lift_angle) triples."""
    for line in RAW.strip().splitlines():
        line = line.strip()
        if not line or "|" not in line:
            continue
        brand, rest = line.split("|", 1)
        for item in rest.split(","):
            item = item.strip()
            if ":" not in item:
                continue
            name, lift = item.rsplit(":", 1)
            try:
                yield brand.strip(), name.strip(), float(lift)
            except ValueError:
                continue
